// API de configuration des règles transformant les anomalies en alertes.
using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using StbMonitoring.Application.Contracts;using StbMonitoring.Application.Interfaces;using StbMonitoring.Domain.Constants;
namespace StbMonitoring.Api.Controllers;
[ApiController,Route("api/alert-rules"),Authorize(Policy=PermissionNames.AlertRulesManage)]public sealed class AlertRulesController(IOperationsService service):ControllerBase
{[HttpGet]public async Task<IActionResult>All(CancellationToken ct)=>Ok(await service.RulesAsync(ct));[HttpPost]public async Task<IActionResult>Create(AlertRuleRequest r,CancellationToken ct)=>Ok(await service.CreateRuleAsync(r,ct));[HttpPut("{id:guid}")]public async Task<IActionResult>Update(Guid id,AlertRuleRequest r,CancellationToken ct)=>Ok(await service.UpdateRuleAsync(id,r,ct));[HttpPatch("{id:guid}/active")]public async Task<IActionResult>Active(Guid id,[FromQuery]bool value,CancellationToken ct){await service.SetRuleActiveAsync(id,value,ct);return NoContent();}[HttpDelete("{id:guid}")]public async Task<IActionResult>Delete(Guid id,CancellationToken ct){await service.DeleteRuleAsync(id,ct);return NoContent();}}
